mapper.select:
SELECT SalesNo AS salesNo, SalesDate AS salesDate, CustCode AS custCode, Qty AS qty, Discount AS discount, Cost AS cost, BankingYn AS bankingYn, Status AS status, SalesYn AS salesYn FROM SalesMaster
SalesYn = 'Y' AND BankingYn = 'N'
AND CustCode = #{custCode}
AND SalesDate BETWEEN #{startDate} AND #{endDate}

mapper.update:
UPDATE OrderDetail
SET Remark = #{remark}
WHERE OrderNo = #{orderNo}
  AND OrderSeq = #{orderSeq}

mapper.select:
SELECT TOP 1 SalesNo
FROM SalesDetail
WHERE OrderNo = #{orderNo}

SELECT SalesDate
FROM SalesMaster
WHERE SalesNo = #{salesNo}

mapper.delete:
DELETE FROM SalesDetail
WHERE OrderNo = #{orderNo}
  AND OrderSeq > #{maxSeq}
